INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g5_2_kor_u5_L01_basic#1','kor',5,2,'u5','L01','g5_2_kor_u5_L01_basic','lesson_basic','K5-2-u5-C2',1,'mc','auto','글에 드러나지 않은 내용을 글의 단서나 자신의 경험, 지식을 바탕으로 짐작하는 것을 무엇이라고 하나요?',ARRAY['K5-2-u5-X02']::text[],false,'{"seq":1,"concept":"K5-2-u5-C2","difficulty":1,"kind":"mc","stem":"글에 드러나지 않은 내용을 글의 단서나 자신의 경험, 지식을 바탕으로 짐작하는 것을 무엇이라고 하나요?","options":[{"t":"추론","correct":true},{"t":"요약","mis":"K5-2-u5-X02"},{"t":"낭독","mis":"K5-2-u5-X02"},{"t":"토의","mis":"K5-2-u5-X02"}],"explanation":["글을 간추리는 일이에요.","소리 내어 읽는 일이에요.","단서로 짐작하며 읽는 것이 추론이에요."]}'::jsonb),
('g5_2_kor_u5_L01_basic#2','kor',5,2,'u5','L01','g5_2_kor_u5_L01_basic','lesson_basic','K5-2-u5-C1',1,'mc','auto','「대장간」 소개 글에 드러난 내용은 어느 것인가요?',ARRAY['K5-2-u5-X09']::text[],false,'{"seq":2,"concept":"K5-2-u5-C1","difficulty":1,"kind":"mc","stem":"「대장간」 소개 글에 드러난 내용은 어느 것인가요?","options":[{"t":"달군 쇠붙이를 집게로 잡고 망치로 두드린다","correct":true},{"t":"만든 물건을 장터에 내다 판다","mis":"K5-2-u5-X09"},{"t":"대장간 사람들은 모두 한 가족이다","mis":"K5-2-u5-X09"},{"t":"대장간은 아침에만 문을 연다","mis":"K5-2-u5-X09"}],"explanation":["글에 쓰여 있지 않아요.","글에 쓰여 있지 않아요.","글에 그대로 나온 내용을 찾아요."],"asset":{"type":"passage","lines":["김홍도의 그림 「대장간」에는 좁은 마당에 여러 사람이 모여 있어요.","한 사람은 벌겋게 달군 쇠붙이를 집게로 꽉 잡고 있어요.","다른 사람들은 커다란 망치를 번갈아 높이 들어 올려요.","「땅! 땅!」 망치가 쇠를 때리는 소리가 귀에 울리는 것 같아요.","한쪽에서는 낫처럼 휘어진 쇠붙이를 숫돌에 쓱쓱 문질러요."],"title":"그림 「대장간」을 소개하는 글"}}'::jsonb),
('g5_2_kor_u5_L01_basic#3','kor',5,2,'u5','L01','g5_2_kor_u5_L01_basic','lesson_basic','K5-2-u5-C1',1,'ox','auto','글에 쓰여 있지 않은 내용도 글의 단서를 바탕으로 짐작할 수 있어요.',ARRAY['K5-2-u5-X01']::text[],false,'{"seq":3,"concept":"K5-2-u5-C1","difficulty":1,"kind":"ox","stem":"글에 쓰여 있지 않은 내용도 글의 단서를 바탕으로 짐작할 수 있어요.","answer":"O","reason_options":[{"t":"글의 단서와 내가 아는 것을 함께 생각하면 짐작할 수 있기 때문에","correct":true},{"t":"글에 쓰여 있지 않으면 알 길이 없기 때문에","mis":"K5-2-u5-X01"}],"mis":"K5-2-u5-X01","explanation":["쓰여 있지 않아도 짐작해요.","단서가 길을 알려 줘요.","이것이 추론이에요."]}'::jsonb),
('g5_2_kor_u5_L01_basic#4','kor',5,2,'u5','L01','g5_2_kor_u5_L01_basic','lesson_basic','K5-2-u5-C3',1,'mc','auto','짝이 아무 말도 하지 않았는데 무슨 일이 있었는지 짐작하게 하는 단서는 어느 것인가요?',ARRAY['K5-2-u5-X06']::text[],false,'{"seq":4,"concept":"K5-2-u5-C3","difficulty":1,"kind":"mc","stem":"짝이 아무 말도 하지 않았는데 무슨 일이 있었는지 짐작하게 하는 단서는 어느 것인가요?","options":[{"t":"무릎에 묻은 흙과 바람 빠진 공","correct":true},{"t":"짝이 앉은 자리의 위치","mis":"K5-2-u5-X06"},{"t":"쉬는 시간이 끝났다는 것","mis":"K5-2-u5-X06"},{"t":"창밖이 보인다는 것","mis":"K5-2-u5-X06"}],"explanation":["일과 관계가 적어요.","누구에게나 같은 일이에요.","흙과 공이 무슨 일이 있었는지 알려 줘요."],"asset":{"type":"passage","lines":["쉬는 시간이 끝나고 짝이 교실로 돌아왔어요.","짝은 아무 말 없이 자리에 앉아 창밖만 바라봐요.","무릎에는 흙이 묻어 있어요.","손에는 바람 빠진 공을 꼭 쥐고 있어요."],"title":"말없이 돌아온 짝"}}'::jsonb),
('g5_2_kor_u5_L01_basic#5','kor',5,2,'u5','L01','g5_2_kor_u5_L01_basic','lesson_basic','K5-2-u5-C2',2,'mc','auto','「대장간」 소개 글로 보아 대장간은 무엇을 하는 곳이라고 짐작할 수 있나요?',ARRAY['K5-2-u5-X09','K5-2-u5-X06']::text[],false,'{"seq":5,"concept":"K5-2-u5-C2","difficulty":2,"kind":"mc","stem":"「대장간」 소개 글로 보아 대장간은 무엇을 하는 곳이라고 짐작할 수 있나요?","options":[{"t":"쇠로 낫이나 호미 같은 연장을 만드는 곳","correct":true},{"t":"그림을 그려 파는 곳","mis":"K5-2-u5-X09"},{"t":"쌀을 찧어 가루로 만드는 곳","mis":"K5-2-u5-X06"},{"t":"글을 베껴 쓰는 곳","mis":"K5-2-u5-X09"}],"explanation":["글과 맞지 않아요.","쇠를 다루는 모습과 맞지 않아요.","쇠를 두드리고 가는 모습이 단서예요."],"asset":{"type":"passage","lines":["김홍도의 그림 「대장간」에는 좁은 마당에 여러 사람이 모여 있어요.","한 사람은 벌겋게 달군 쇠붙이를 집게로 꽉 잡고 있어요.","다른 사람들은 커다란 망치를 번갈아 높이 들어 올려요.","「땅! 땅!」 망치가 쇠를 때리는 소리가 귀에 울리는 것 같아요.","한쪽에서는 낫처럼 휘어진 쇠붙이를 숫돌에 쓱쓱 문질러요."],"title":"그림 「대장간」을 소개하는 글"}}'::jsonb),
('g5_2_kor_u5_L01_basic#6','kor',5,2,'u5','L01','g5_2_kor_u5_L01_basic','lesson_basic','K5-2-u5-C6',2,'mc','auto','대장간이 연장을 만드는 곳이라고 짐작하게 한 단서로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X06']::text[],false,'{"seq":6,"concept":"K5-2-u5-C6","difficulty":2,"kind":"mc","stem":"대장간이 연장을 만드는 곳이라고 짐작하게 한 단서로 알맞은 것은 어느 것인가요?","options":[{"t":"낫처럼 휘어진 쇠붙이를 숫돌에 간다","correct":true},{"t":"그림을 그린 사람은 김홍도이다","mis":"K5-2-u5-X06"},{"t":"좁은 마당에 여러 사람이 모여 있다","mis":"K5-2-u5-X06"},{"t":"글쓴이가 그림을 오래 보았다","mis":"K5-2-u5-X06"}],"explanation":["누가 그렸는지는 쓰임과 관계없어요.","모인 것만으로는 알기 어려워요.","낫 모양 쇠를 가는 모습이 단서예요."],"asset":{"type":"passage","lines":["김홍도의 그림 「대장간」에는 좁은 마당에 여러 사람이 모여 있어요.","한 사람은 벌겋게 달군 쇠붙이를 집게로 꽉 잡고 있어요.","다른 사람들은 커다란 망치를 번갈아 높이 들어 올려요.","「땅! 땅!」 망치가 쇠를 때리는 소리가 귀에 울리는 것 같아요.","한쪽에서는 낫처럼 휘어진 쇠붙이를 숫돌에 쓱쓱 문질러요."],"title":"그림 「대장간」을 소개하는 글"}}'::jsonb),
('g5_2_kor_u5_L01_basic#7','kor',5,2,'u5','L01','g5_2_kor_u5_L01_basic','lesson_basic','K5-2-u5-C4',2,'match','auto','이 단원에서 배울 내용과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u5-C4","difficulty":2,"kind":"match","stem":"이 단원에서 배울 내용과 하는 일을 알맞게 이으세요.","pairs":[{"l":"추론하며 읽는 방법","r":"단서와 경험·지식으로 짐작하기"},{"l":"함축된 표현","r":"숨은 뜻을 찾아 읽기"},{"l":"글쓴이의 의도","r":"글을 쓴 까닭 짐작하기"}],"mis":"K5-2-u5-X04","explanation":["짐작하는 방법부터 익혀요.","숨은 뜻을 찾아요.","글을 쓴 까닭까지 읽어요."]}'::jsonb),
('g5_2_kor_u5_L01_basic#8','kor',5,2,'u5','L01','g5_2_kor_u5_L01_basic','lesson_basic','K5-2-u5-C7',2,'mc','auto','「낫과 호미는 쇠로 만든 농기구예요.」라는 생각은 추론의 어떤 바탕에 해당하나요?',ARRAY['K5-2-u5-X05','K5-2-u5-X07']::text[],false,'{"seq":8,"concept":"K5-2-u5-C7","difficulty":2,"kind":"mc","stem":"「낫과 호미는 쇠로 만든 농기구예요.」라는 생각은 추론의 어떤 바탕에 해당하나요?","options":[{"t":"내가 알고 있는 지식","correct":true},{"t":"글에 쓰인 문장","mis":"K5-2-u5-X05"},{"t":"글쓴이의 이름","mis":"K5-2-u5-X07"},{"t":"그림의 제목","mis":"K5-2-u5-X07"}],"explanation":["글에 쓰여 있지 않아요.","이름은 바탕이 아니에요.","내가 아는 것도 추론의 바탕이에요."]}'::jsonb),
('g5_2_kor_u5_L01_basic#9','kor',5,2,'u5','L01','g5_2_kor_u5_L01_basic','lesson_basic','K5-2-u5-C9',2,'error','auto','짝의 마음을 짐작한 친구들의 말이에요. 추론이라고 하기 어려운 말은 어느 것인가요?',ARRAY['K5-2-u5-X09','K5-2-u5-X08']::text[],false,'{"seq":9,"concept":"K5-2-u5-C9","difficulty":2,"kind":"error","stem":"짝의 마음을 짐작한 친구들의 말이에요. 추론이라고 하기 어려운 말은 어느 것인가요?","options":[{"t":"「짝은 아마 외계인을 만났을 거야.」","correct":true,"mis_target":"K5-2-u5-X09"},{"t":"「흙이 묻은 걸 보니 공을 차다 넘어졌나 봐.」","mis":"K5-2-u5-X08"},{"t":"「공이 바람 빠진 걸 보니 놀이가 잘 안 됐나 봐.」","mis":"K5-2-u5-X08"}],"explanation":["흙이라는 단서가 있어요.","공이라는 단서가 있어요.","근거 없이 지어낸 말은 추론이 아니에요."],"asset":{"type":"passage","lines":["쉬는 시간이 끝나고 짝이 교실로 돌아왔어요.","짝은 아무 말 없이 자리에 앉아 창밖만 바라봐요.","무릎에는 흙이 묻어 있어요.","손에는 바람 빠진 공을 꼭 쥐고 있어요."],"title":"말없이 돌아온 짝"}}'::jsonb),
('g5_2_kor_u5_L01_basic#10','kor',5,2,'u5','L01','g5_2_kor_u5_L01_basic','lesson_basic','K5-2-u5-C8',3,'mc','auto','짝의 마음을 짐작해 말할 때 가장 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u5-X08','K5-2-u5-X09','K5-2-u5-X01']::text[],false,'{"seq":10,"concept":"K5-2-u5-C8","difficulty":3,"kind":"mc","stem":"짝의 마음을 짐작해 말할 때 가장 알맞은 말은 어느 것인가요?","options":[{"t":"「바람 빠진 공을 쥐고 있는 걸 보니, 놀이가 뜻대로 안 돼 속상한 것 같아.」","correct":true},{"t":"「그냥 그런 느낌이 들어.」","mis":"K5-2-u5-X08"},{"t":"「짝은 원래 늘 화가 나 있어.」","mis":"K5-2-u5-X09"},{"t":"「말을 안 했으니 아무것도 알 수 없어.」","mis":"K5-2-u5-X01"}],"explanation":["근거가 없어요.","단서와 관계없는 말이에요.","단서를 들어 짐작했어요."],"asset":{"type":"passage","lines":["쉬는 시간이 끝나고 짝이 교실로 돌아왔어요.","짝은 아무 말 없이 자리에 앉아 창밖만 바라봐요.","무릎에는 흙이 묻어 있어요.","손에는 바람 빠진 공을 꼭 쥐고 있어요."],"title":"말없이 돌아온 짝"}}'::jsonb),
('g5_2_kor_u5_L01_challenge#1','kor',5,2,'u5','L01','g5_2_kor_u5_L01_challenge','lesson_challenge','K5-2-u5-C9',2,'ox','auto','추론은 아무렇게나 상상하는 것이라 근거가 없어도 돼요.',ARRAY['K5-2-u5-X09']::text[],false,'{"seq":1,"concept":"K5-2-u5-C9","difficulty":2,"kind":"ox","stem":"추론은 아무렇게나 상상하는 것이라 근거가 없어도 돼요.","answer":"X","reason_options":[{"t":"추론은 글의 단서나 경험·지식이라는 근거를 바탕으로 짐작하는 것이기 때문에","correct":true},{"t":"짐작은 사람마다 마음대로 해도 되기 때문에","mis":"K5-2-u5-X09"}],"mis":"K5-2-u5-X09","explanation":["근거가 있어야 해요.","마음대로 지어내는 것이 아니에요.","단서와 경험·지식이 근거예요."]}'::jsonb),
('g5_2_kor_u5_L01_challenge#2','kor',5,2,'u5','L01','g5_2_kor_u5_L01_challenge','lesson_challenge','K5-2-u5-C3',2,'mc','auto','생활 속에서 추론한 예로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X02','K5-2-u5-X03']::text[],false,'{"seq":2,"concept":"K5-2-u5-C3","difficulty":2,"kind":"mc","stem":"생활 속에서 추론한 예로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"먹구름이 몰려오는 것을 보고 우산을 챙겼다","correct":true},{"t":"달력을 보고 오늘 날짜를 읽었다","mis":"K5-2-u5-X02"},{"t":"시간표에 적힌 과목을 그대로 읽었다","mis":"K5-2-u5-X02"},{"t":"추론은 글 읽을 때만 하므로 생활 속 예는 없다","mis":"K5-2-u5-X03"}],"explanation":["쓰인 것을 그대로 읽었어요.","쓰인 것을 그대로 읽었어요.","먹구름을 단서로 비를 짐작했어요."]}'::jsonb),
('g5_2_kor_u5_L01_challenge#3','kor',5,2,'u5','L01','g5_2_kor_u5_L01_challenge','lesson_challenge','K5-2-u5-C10',3,'mc','auto','두 친구의 짐작을 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u5-X10','K5-2-u5-X09','K5-2-u5-X01']::text[],false,'{"seq":3,"concept":"K5-2-u5-C10","difficulty":3,"kind":"mc","stem":"두 친구의 짐작을 바르게 말한 것은 어느 것인가요?","options":[{"t":"짐작은 하나가 아닐 수 있지만 어떤 단서를 근거로 했는지 말해야 한다","correct":true},{"t":"둘 가운데 하나는 반드시 틀렸다","mis":"K5-2-u5-X10"},{"t":"근거 없이 말해도 둘 다 맞다","mis":"K5-2-u5-X09"},{"t":"글에 쓰여 있지 않으니 둘 다 말하면 안 된다","mis":"K5-2-u5-X01"}],"explanation":["정답이 하나뿐인 것은 아니에요.","근거는 꼭 있어야 해요.","두 친구 모두 단서를 들었어요."],"asset":{"type":"speech","turns":[{"who":"예린","text":"대장간은 칼을 만드는 곳이야. 쇠를 두드려 날을 세우잖아."},{"who":"도윤","text":"대장간은 농기구를 만드는 곳이야. 낫처럼 휘어진 쇠를 갈고 있잖아."}]}}'::jsonb),
('g5_2_kor_u5_L01_challenge#4','kor',5,2,'u5','L01','g5_2_kor_u5_L01_challenge','lesson_challenge','K5-2-u5-C2',3,'mc','auto','추론에 대한 설명으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X02','K5-2-u5-X09','K5-2-u5-X01']::text[],false,'{"seq":4,"concept":"K5-2-u5-C2","difficulty":3,"kind":"mc","stem":"추론에 대한 설명으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"글의 단서와 내 경험·지식을 함께 써서 쓰여 있지 않은 내용을 짐작하는 것","correct":true},{"t":"글에 쓰인 문장을 그대로 옮겨 적는 것","mis":"K5-2-u5-X02"},{"t":"글과 관계없이 떠오르는 대로 이야기를 지어내는 것","mis":"K5-2-u5-X09"},{"t":"글에 쓰여 있지 않은 내용은 모른다고 하는 것","mis":"K5-2-u5-X01"}],"explanation":["옮겨 적기는 추론이 아니에요.","근거 없는 상상이에요.","단서와 경험·지식으로 짐작해요."]}'::jsonb),
('g5_2_kor_u5_L01_challenge#5','kor',5,2,'u5','L01','g5_2_kor_u5_L01_challenge','lesson_challenge','K5-2-u5-C4',3,'mc','auto','이 단원에서 배우는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X04']::text[],false,'{"seq":5,"concept":"K5-2-u5-C4","difficulty":3,"kind":"mc","stem":"이 단원에서 배우는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"추론하며 읽는 방법 → 글쓴이의 생각 → 함축된 표현 → 글쓴이의 의도","correct":true},{"t":"글쓴이의 의도 → 함축된 표현 → 추론하며 읽는 방법 → 글쓴이의 생각","mis":"K5-2-u5-X04"},{"t":"함축된 표현 → 글쓴이의 의도 → 글쓴이의 생각 → 추론하며 읽는 방법","mis":"K5-2-u5-X04"},{"t":"글쓴이의 생각 → 추론하며 읽는 방법 → 글쓴이의 의도 → 함축된 표현","mis":"K5-2-u5-X04"}],"explanation":["의도는 나중이에요.","방법을 먼저 익혀요.","방법부터 익혀 의도까지 읽어요."]}'::jsonb),
('g5_2_kor_u5_L01_challenge#6','kor',5,2,'u5','L01','g5_2_kor_u5_L01_challenge','lesson_challenge','K5-2-u5-C6',3,'error','auto','「대장간」 소개 글에서 친구들이 찾은 단서예요. 연장을 만드는 곳이라는 짐작의 단서로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u5-X06','K5-2-u5-X07']::text[],false,'{"seq":6,"concept":"K5-2-u5-C6","difficulty":3,"kind":"error","stem":"「대장간」 소개 글에서 친구들이 찾은 단서예요. 연장을 만드는 곳이라는 짐작의 단서로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「그림을 그린 사람은 김홍도이다.」","correct":true,"mis_target":"K5-2-u5-X06"},{"t":"「달군 쇠붙이를 망치로 두드린다.」","mis":"K5-2-u5-X07"},{"t":"「낫처럼 휘어진 쇠붙이를 숫돌에 간다.」","mis":"K5-2-u5-X07"}],"explanation":["쇠를 다루는 단서예요.","연장 모양의 단서예요.","그린 사람은 대장간의 쓰임과 관계없어요."],"asset":{"type":"passage","lines":["김홍도의 그림 「대장간」에는 좁은 마당에 여러 사람이 모여 있어요.","한 사람은 벌겋게 달군 쇠붙이를 집게로 꽉 잡고 있어요.","다른 사람들은 커다란 망치를 번갈아 높이 들어 올려요.","「땅! 땅!」 망치가 쇠를 때리는 소리가 귀에 울리는 것 같아요.","한쪽에서는 낫처럼 휘어진 쇠붙이를 숫돌에 쓱쓱 문질러요."],"title":"그림 「대장간」을 소개하는 글"}}'::jsonb),
('g5_2_kor_u5_L01_challenge#7','kor',5,2,'u5','L01','g5_2_kor_u5_L01_challenge','lesson_challenge','K5-2-u5-C7',3,'mc','auto','대장간 사람들이 쇠를 달구어 두드리는 까닭을 짐작할 때 도움이 되는 지식은 어느 것인가요?',ARRAY['K5-2-u5-X07']::text[],false,'{"seq":7,"concept":"K5-2-u5-C7","difficulty":3,"kind":"mc","stem":"대장간 사람들이 쇠를 달구어 두드리는 까닭을 짐작할 때 도움이 되는 지식은 어느 것인가요?","options":[{"t":"쇠는 뜨겁게 달구면 물러져 모양을 바꾸기 쉽다","correct":true},{"t":"쇠는 물에 넣으면 녹아 없어진다","mis":"K5-2-u5-X07"},{"t":"쇠는 차가울수록 잘 휘어진다","mis":"K5-2-u5-X07"},{"t":"쇠는 망치로 두드리면 가벼워진다","mis":"K5-2-u5-X07"}],"explanation":["바른 지식이 아니에요.","바른 지식이 아니에요.","바른 지식이 추론을 돕습니다."]}'::jsonb),
('g5_2_kor_u5_L01_challenge#8','kor',5,2,'u5','L01','g5_2_kor_u5_L01_challenge','lesson_challenge','K5-2-u5-C2',4,'essay','teacher','「대장간」 소개 글을 읽고 대장간이 무엇을 하는 곳인지 짐작해 쓰고, 그렇게 짐작한 단서와 내가 아는 것을 함께 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u5-C2","difficulty":4,"kind":"essay","stem":"「대장간」 소개 글을 읽고 대장간이 무엇을 하는 곳인지 짐작해 쓰고, 그렇게 짐작한 단서와 내가 아는 것을 함께 쓰세요.","answer_guide":{"answer":"예: 대장간은 쇠로 낫이나 호미 같은 연장을 만드는 곳이다. 글에서 달군 쇠를 망치로 두드리고 낫처럼 휘어진 쇠를 숫돌에 간다는 단서를 찾았고, 낫과 호미가 쇠로 만든 농기구라는 것을 알고 있어서 그렇게 짐작했다.","scoring_points":["대장간의 쓰임을 짐작했는가","글의 단서를 썼는가","내가 아는 것을 함께 썼는가"]},"explanation":["짐작을 써요.","단서를 찾아요.","아는 것을 더해요."],"asset":{"type":"passage","lines":["김홍도의 그림 「대장간」에는 좁은 마당에 여러 사람이 모여 있어요.","한 사람은 벌겋게 달군 쇠붙이를 집게로 꽉 잡고 있어요.","다른 사람들은 커다란 망치를 번갈아 높이 들어 올려요.","「땅! 땅!」 망치가 쇠를 때리는 소리가 귀에 울리는 것 같아요.","한쪽에서는 낫처럼 휘어진 쇠붙이를 숫돌에 쓱쓱 문질러요."],"title":"그림 「대장간」을 소개하는 글"}}'::jsonb),
('g5_2_kor_u5_L01_challenge#9','kor',5,2,'u5','L01','g5_2_kor_u5_L01_challenge','lesson_challenge','K5-2-u5-C3',4,'essay','teacher','말하지 않아도 다른 사람의 마음이나 상황을 짐작한 경험을 하나 쓰고, 무엇을 단서로 짐작했는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u5-C3","difficulty":4,"kind":"essay","stem":"말하지 않아도 다른 사람의 마음이나 상황을 짐작한 경험을 하나 쓰고, 무엇을 단서로 짐작했는지 쓰세요.","answer_guide":{"answer":"예: 엄마가 퇴근하고 들어와 말없이 소파에 기대 눈을 감았다. 가방을 아무렇게나 내려놓고 어깨를 주무르는 모습을 단서로 오늘 일이 많아 무척 피곤하다고 짐작했다. 그래서 물 한 잔을 가져다드렸다.","scoring_points":["경험을 구체적으로 썼는가","단서를 썼는가","짐작한 마음이나 상황을 썼는가"]},"explanation":["경험을 떠올려요.","단서를 찾아요.","짐작을 써요."]}'::jsonb),
('g5_2_kor_u5_L01_challenge#10','kor',5,2,'u5','L01','g5_2_kor_u5_L01_challenge','lesson_challenge','K5-2-u5-C8',4,'essay','teacher','「말없이 돌아온 짝」을 보고 짝에게 무슨 일이 있었는지 짐작해 쓰고, 「~을 보니 ~인 것 같다」 꼴로 근거를 밝혀 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u5-C8","difficulty":4,"kind":"essay","stem":"「말없이 돌아온 짝」을 보고 짝에게 무슨 일이 있었는지 짐작해 쓰고, 「~을 보니 ~인 것 같다」 꼴로 근거를 밝혀 쓰세요.","answer_guide":{"answer":"예: 무릎에 흙이 묻은 것을 보니 운동장에서 공을 차다 넘어진 것 같다. 바람 빠진 공을 꼭 쥐고 창밖만 보는 것을 보니 공이 망가져 놀이를 못 해서 속상한 것 같다.","scoring_points":["일어난 일을 짐작했는가","단서를 근거로 밝혔는가","정해진 꼴로 썼는가"]},"explanation":["짐작해요.","근거를 밝혀요.","꼴을 지켜요."],"asset":{"type":"passage","lines":["쉬는 시간이 끝나고 짝이 교실로 돌아왔어요.","짝은 아무 말 없이 자리에 앉아 창밖만 바라봐요.","무릎에는 흙이 묻어 있어요.","손에는 바람 빠진 공을 꼭 쥐고 있어요."],"title":"말없이 돌아온 짝"}}'::jsonb),
('g5_2_kor_u5_L02_basic#1','kor',5,2,'u5','L02','g5_2_kor_u5_L02_basic','lesson_basic','K5-2-u5-C5',1,'mc','auto','로버트 훅은 현미경으로 본 것을 어떻게 했나요?',ARRAY['K5-2-u5-X05']::text[],false,'{"seq":1,"concept":"K5-2-u5-C5","difficulty":1,"kind":"mc","stem":"로버트 훅은 현미경으로 본 것을 어떻게 했나요?","options":[{"t":"커다란 그림으로 그려 책으로 펴냈다","correct":true},{"t":"편지로 써서 보냈다","mis":"K5-2-u5-X05"},{"t":"사진으로 찍어 걸었다","mis":"K5-2-u5-X05"},{"t":"아무에게도 보여 주지 않았다","mis":"K5-2-u5-X05"}],"explanation":["레이우엔훅이 한 일이에요.","글에 없어요.","그림을 그려 책으로 펴냈어요."],"asset":{"type":"passage","lines":["아주 오래전, 영국의 과학자 로버트 훅은 직접 만든 현미경으로","작은 생물을 들여다보고, 본 것을 커다란 그림으로 그려 책으로 펴냈어요.","책에 실린 벼룩 그림은 접힌 종이를 펼쳐야 다 보일 만큼 컸어요.","사람들은 깨알보다 작은 벌레에 털과 마디가 많다는 것에 놀랐어요.","몇 해 뒤, 네덜란드의 옷감 상인 레이우엔훅도 손수 현미경을 만들었어요.","그는 빗물 한 방울을 들여다보다가 눈을 떼지 못했어요.","맑아 보이던 물방울 속에서 아주 작은 생명체들이 바쁘게 헤엄쳤거든요.","그가 본 것을 편지로 알렸지만, 처음에는 믿는 사람이 거의 없었어요."],"title":"현미경이 열어 준 작은 세상"}}'::jsonb),
('g5_2_kor_u5_L02_basic#2','kor',5,2,'u5','L02','g5_2_kor_u5_L02_basic','lesson_basic','K5-2-u5-C5',1,'mc','auto','레이우엔훅이 현미경으로 들여다본 것은 무엇인가요?',ARRAY['K5-2-u5-X05']::text[],false,'{"seq":2,"concept":"K5-2-u5-C5","difficulty":1,"kind":"mc","stem":"레이우엔훅이 현미경으로 들여다본 것은 무엇인가요?","options":[{"t":"빗물 한 방울","correct":true},{"t":"벼룩","mis":"K5-2-u5-X05"},{"t":"깨알","mis":"K5-2-u5-X05"},{"t":"옷감","mis":"K5-2-u5-X05"}],"explanation":["로버트 훅이 그린 것이에요.","견주는 말로만 나와요.","빗물 한 방울을 들여다보았어요."],"asset":{"type":"passage","lines":["아주 오래전, 영국의 과학자 로버트 훅은 직접 만든 현미경으로","작은 생물을 들여다보고, 본 것을 커다란 그림으로 그려 책으로 펴냈어요.","책에 실린 벼룩 그림은 접힌 종이를 펼쳐야 다 보일 만큼 컸어요.","사람들은 깨알보다 작은 벌레에 털과 마디가 많다는 것에 놀랐어요.","몇 해 뒤, 네덜란드의 옷감 상인 레이우엔훅도 손수 현미경을 만들었어요.","그는 빗물 한 방울을 들여다보다가 눈을 떼지 못했어요.","맑아 보이던 물방울 속에서 아주 작은 생명체들이 바쁘게 헤엄쳤거든요.","그가 본 것을 편지로 알렸지만, 처음에는 믿는 사람이 거의 없었어요."],"title":"현미경이 열어 준 작은 세상"}}'::jsonb),
('g5_2_kor_u5_L02_basic#3','kor',5,2,'u5','L02','g5_2_kor_u5_L02_basic','lesson_basic','K5-2-u5-C6',1,'mc','auto','글에 드러나지 않은 내용을 짐작할 때 글에서 찾는 실마리를 무엇이라고 하나요?',ARRAY['K5-2-u5-X06']::text[],false,'{"seq":3,"concept":"K5-2-u5-C6","difficulty":1,"kind":"mc","stem":"글에 드러나지 않은 내용을 짐작할 때 글에서 찾는 실마리를 무엇이라고 하나요?","options":[{"t":"단서","correct":true},{"t":"제목","mis":"K5-2-u5-X06"},{"t":"차례","mis":"K5-2-u5-X06"},{"t":"쪽수","mis":"K5-2-u5-X06"}],"explanation":["제목도 단서가 될 수 있지만 실마리 모두를 가리키지는 않아요.","실마리가 아니에요.","짐작의 실마리를 단서라고 해요."]}'::jsonb),
