('g5_2_kor_u5_review_c#15','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C23',2,'mc','auto','「텃밭의 빈 의자」의 사건을 차례대로 늘어놓은 것은 어느 것인가요?',ARRAY['K5-2-u5-X23']::text[],false,'{"seq":15,"concept":"K5-2-u5-C23","difficulty":2,"kind":"mc","stem":"「텃밭의 빈 의자」의 사건을 차례대로 늘어놓은 것은 어느 것인가요?","options":[{"t":"할아버지가 의자에 앉음 → 의자가 빔 → 쪽지가 놓임 → 할아버지가 돌아옴","correct":true},{"t":"쪽지가 놓임 → 의자가 빔 → 할아버지가 의자에 앉음 → 할아버지가 돌아옴","mis":"K5-2-u5-X23"},{"t":"할아버지가 돌아옴 → 의자가 빔 → 쪽지가 놓임 → 할아버지가 의자에 앉음","mis":"K5-2-u5-X23"},{"t":"의자가 빔 → 할아버지가 돌아옴 → 할아버지가 의자에 앉음 → 쪽지가 놓임","mis":"K5-2-u5-X23"}],"explanation":["차례가 섞였어요.","차례가 섞였어요.","일어난 차례대로예요."],"asset":{"type":"passage","lines":["학교 텃밭 끝에는 낡은 나무 의자가 하나 있었어요.","경비 할아버지는 날마다 그 의자에 앉아 아이들이 심은 상추를 바라보았어요.","어느 날부터 의자가 비어 있었어요. 할아버지의 모자도 보이지 않았어요.","아이들은 상추에 물을 주며 자꾸 의자 쪽을 돌아보았어요.","며칠 뒤, 의자 위에 아이들이 쓴 쪽지가 하나둘 놓이기 시작했어요.","「할아버지, 상추가 할아버지를 기다려요.」","다시 돌아온 할아버지는 쪽지를 한 장씩 펴 보며 한참 말이 없었어요.","그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요."],"title":"텃밭의 빈 의자"}}'::jsonb),
('g5_2_kor_u5_review_c#16','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C32',2,'mc','auto','친구의 감정 카드를 보고 짐작한 뒤 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X32','K5-2-u5-X31','K5-2-u5-X22']::text[],false,'{"seq":16,"concept":"K5-2-u5-C32","difficulty":2,"kind":"mc","stem":"친구의 감정 카드를 보고 짐작한 뒤 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「혹시 서운했던 거야? 내 짐작이 맞는지 알려 줘.」","correct":true},{"t":"「넌 분명 화난 거야. 아니라고 해도 소용없어.」","mis":"K5-2-u5-X32"},{"t":"「무슨 뜻인지 모르겠으니 감정 낱말로 다시 써.」","mis":"K5-2-u5-X31"},{"t":"「카드 놀이는 장난이야.」","mis":"K5-2-u5-X22"}],"explanation":["우기는 말이에요.","약속과 달라요.","짐작을 확인해요."]}'::jsonb),
('g5_2_kor_u5_review_c#17','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C17',3,'error','auto','「텃밭의 빈 의자」를 읽고 나눈 말이에요. 함축된 표현을 잘못 이해한 말은 어느 것인가요?',ARRAY['K5-2-u5-X18','K5-2-u5-X17']::text[],false,'{"seq":17,"concept":"K5-2-u5-C17","difficulty":3,"kind":"error","stem":"「텃밭의 빈 의자」를 읽고 나눈 말이에요. 함축된 표현을 잘못 이해한 말은 어느 것인가요?","options":[{"t":"「상추가 할아버지를 기다린다니, 상추가 정말 말을 하나 봐.」","correct":true,"mis_target":"K5-2-u5-X18"},{"t":"「비가 그치고 해가 났다는 건 모두의 마음이 밝아졌다는 뜻 같아.」","mis":"K5-2-u5-X17"},{"t":"「상추가 기다린다는 건 아이들이 기다린다는 말이야.」","mis":"K5-2-u5-X17"}],"explanation":["숨은 뜻을 읽었어요.","숨은 뜻을 읽었어요.","겉뜻으로만 읽었어요."],"asset":{"type":"passage","lines":["학교 텃밭 끝에는 낡은 나무 의자가 하나 있었어요.","경비 할아버지는 날마다 그 의자에 앉아 아이들이 심은 상추를 바라보았어요.","어느 날부터 의자가 비어 있었어요. 할아버지의 모자도 보이지 않았어요.","아이들은 상추에 물을 주며 자꾸 의자 쪽을 돌아보았어요.","며칠 뒤, 의자 위에 아이들이 쓴 쪽지가 하나둘 놓이기 시작했어요.","「할아버지, 상추가 할아버지를 기다려요.」","다시 돌아온 할아버지는 쪽지를 한 장씩 펴 보며 한참 말이 없었어요.","그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요."],"title":"텃밭의 빈 의자"}}'::jsonb),
('g5_2_kor_u5_review_c#18','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C13',3,'error','auto','「골목의 화분」에서 글쓴이의 생각을 찾은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u5-X13','K5-2-u5-X14']::text[],false,'{"seq":18,"concept":"K5-2-u5-C13","difficulty":3,"kind":"error","stem":"「골목의 화분」에서 글쓴이의 생각을 찾은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「마지막 문장에 글쓴이의 생각이 그대로 적혀 있으니 그것만 읽으면 돼.」","correct":true,"mis_target":"K5-2-u5-X13"},{"t":"「이웃들이 따라 한 변화를 보면 글쓴이의 생각이 보여.」","mis":"K5-2-u5-X14"},{"t":"「옷을 갈아입는다는 표현에 생각이 담겨 있어.」","mis":"K5-2-u5-X14"}],"explanation":["변화가 단서예요.","함축된 표현이 단서예요.","그대로 적혀 있지 않아요."],"asset":{"type":"passage","lines":["우리 동네 낡은 골목은 늘 회색빛이었어요.","사람들은 고개를 숙인 채 빠르게 지나갔지요.","어느 봄날, 맨 끝 집 할머니가 대문 앞에 작은 화분 하나를 내놓았어요.","다음 날에도, 그다음 날에도 화분은 하나씩 늘었어요.","「왜 날마다 내놓으세요?」 이웃이 묻자 할머니는 웃기만 했어요.","세 해가 지나자 이웃들도 자기 집 앞에 화분을 내놓았어요.","사람들이 걸음을 늦추고 꽃 이름을 물어요.","회색 골목이 이제는 계절마다 옷을 갈아입어요."],"title":"골목의 화분"}}'::jsonb),
('g5_2_kor_u5_review_c#19','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C33',3,'error','auto','친구가 「가슴에 돌덩이가 얹혔어.」라는 카드를 냈어요. 공감하는 말로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u5-X33','K5-2-u5-X32']::text[],false,'{"seq":19,"concept":"K5-2-u5-C33","difficulty":3,"kind":"error","stem":"친구가 「가슴에 돌덩이가 얹혔어.」라는 카드를 냈어요. 공감하는 말로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「돌덩이가 얹혔다고? 그럼 힘 좀 세겠네!」","correct":true,"mis_target":"K5-2-u5-X33"},{"t":"「마음이 많이 무거웠구나. 무슨 일인지 들어 줄게.」","mis":"K5-2-u5-X32"},{"t":"「걱정되는 일이 있었구나. 나도 같이 생각해 볼게.」","mis":"K5-2-u5-X32"}],"explanation":["마음을 알아줘요.","마음을 알아줘요.","놀리는 말이에요."]}'::jsonb),
('g5_2_kor_u5_review_c#20','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C9',3,'mc','auto','추론과 아무렇게나 상상하기를 가르는 기준으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X09','K5-2-u5-X10']::text[],false,'{"seq":20,"concept":"K5-2-u5-C9","difficulty":3,"kind":"mc","stem":"추론과 아무렇게나 상상하기를 가르는 기준으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"왜 그렇게 생각했는지 단서나 경험·지식으로 말할 수 있는가","correct":true},{"t":"짐작이 재미있는가","mis":"K5-2-u5-X09"},{"t":"짐작이 긴가","mis":"K5-2-u5-X09"},{"t":"친구들이 많이 찬성하는가","mis":"K5-2-u5-X10"}],"explanation":["재미는 기준이 아니에요.","길이는 기준이 아니에요.","근거가 기준이에요."]}'::jsonb),
('g5_2_kor_u5_review_c#21','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C29',3,'mc','auto','같은 글을 두고 해석이 갈릴 때 가장 알맞은 태도는 어느 것인가요?',ARRAY['K5-2-u5-X10','K5-2-u5-X29']::text[],false,'{"seq":21,"concept":"K5-2-u5-C29","difficulty":3,"kind":"mc","stem":"같은 글을 두고 해석이 갈릴 때 가장 알맞은 태도는 어느 것인가요?","options":[{"t":"서로 근거를 말하고 글 속 단서와 더 잘 맞는 해석을 함께 찾는다","correct":true},{"t":"내 해석만 옳다고 우긴다","mis":"K5-2-u5-X10"},{"t":"근거는 따지지 않고 다 맞다고 한다","mis":"K5-2-u5-X29"},{"t":"해석이 갈리면 그 글은 나쁜 글이다","mis":"K5-2-u5-X29"}],"explanation":["우기지 않아요.","근거를 따져요.","함께 찾아요."]}'::jsonb),
('g5_2_kor_u5_review_c#22','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C35',3,'error','auto','친구가 쓴 쪽지예요. 낱말을 바르게 쓰지 않은 것은 어느 것인가요?',ARRAY['K5-2-u5-X35','K5-2-u5-X36']::text[],false,'{"seq":22,"concept":"K5-2-u5-C35","difficulty":3,"kind":"error","stem":"친구가 쓴 쪽지예요. 낱말을 바르게 쓰지 않은 것은 어느 것인가요?","options":[{"t":"「해쌀로 지은 밥이 고소했어.」","correct":true,"mis_target":"K5-2-u5-X35"},{"t":"「좁쌀이 노랗고 동글동글해.」","mis":"K5-2-u5-X36"},{"t":"「암탉이 알을 낳았어.」","mis":"K5-2-u5-X36"}],"explanation":["바르게 썼어요.","바르게 썼어요.","햅쌀이 바른 말이에요."]}'::jsonb),
('g5_2_kor_u5_review_c#23','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C35',4,'essay','teacher','ㅂ 소리가 덧나는 낱말 하나와 ㅎ 소리가 덧나는 낱말 하나를 골라 각각 짧은 문장을 쓰고, 어떤 두 낱말이 어울렸는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u5-C35","difficulty":4,"kind":"essay","stem":"ㅂ 소리가 덧나는 낱말 하나와 ㅎ 소리가 덧나는 낱말 하나를 골라 각각 짧은 문장을 쓰고, 어떤 두 낱말이 어울렸는지 쓰세요.","answer_guide":{"answer":"예: 「농부가 논에 볍씨를 뿌렸다.」 — 벼와 씨가 어울렸다. 「마당에서 수탉이 힘차게 울었다.」 — 수와 닭이 어울렸다.","scoring_points":["ㅂ 소리 낱말로 문장을 썼는가","ㅎ 소리 낱말로 문장을 썼는가","어울린 두 낱말을 바르게 썼는가"]},"explanation":["ㅂ 소리 낱말이에요.","ㅎ 소리 낱말이에요.","어울린 낱말을 밝혀요."],"asset":{"type":"passage","lines":["벼 + 씨 → 볍씨 · 해 + 쌀 → 햅쌀 · 메 + 쌀 → 멥쌀 · 조 + 쌀 → 좁쌀","수 + 닭 → 수탉 · 암 + 닭 → 암탉","머리 + 가락 → 머리카락 · 안 + 밖 → 안팎 · 살 + 고기 → 살코기"],"title":"두 낱말이 어울릴 때 소리가 덧나는 낱말"}}'::jsonb),
('g5_2_kor_u5_review_c#24','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C34',4,'essay','teacher','광고나 뉴스, 영상 가운데 하나를 떠올려 드러나지 않은 뜻이나 만든 사람의 의도를 짐작해 쓰고, 그렇게 짐작한 단서를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u5-C34","difficulty":4,"kind":"essay","stem":"광고나 뉴스, 영상 가운데 하나를 떠올려 드러나지 않은 뜻이나 만든 사람의 의도를 짐작해 쓰고, 그렇게 짐작한 단서를 쓰세요.","answer_guide":{"answer":"예: 운동화 광고에서 유명한 선수가 그 신발을 신고 빠르게 달린다. 이 신발을 신으면 나도 빨리 달릴 수 있다고 느끼게 해서 신발을 사게 하려는 의도가 있다. 선수가 웃으며 신발을 크게 보여 주는 장면이 단서이다.","scoring_points":["광고·뉴스·영상 하나를 골랐는가","드러나지 않은 뜻이나 의도를 짐작했는가","단서를 썼는가"]},"explanation":["하나를 골라요.","의도를 짐작해요.","단서를 써요."]}'::jsonb),
('g5_2_kor_u5_review_c#25','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C10',4,'essay','teacher','「골목의 화분」이나 「텃밭의 빈 의자」를 읽고 친구와 짐작이 달랐던 점을 하나 떠올려, 서로 다른 짐작을 견주는 대화를 근거와 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u5-C10","difficulty":4,"kind":"essay","stem":"「골목의 화분」이나 「텃밭의 빈 의자」를 읽고 친구와 짐작이 달랐던 점을 하나 떠올려, 서로 다른 짐작을 견주는 대화를 근거와 함께 쓰세요.","answer_guide":{"answer":"예: 나 — 「할아버지는 아파서 못 나오신 것 같아. 모자도 안 보였잖아.」 친구 — 「나는 멀리 사는 가족을 보러 가신 것 같아. 며칠 뒤 돌아오셨잖아.」 나 — 「둘 다 단서가 있네. 글에 쓰여 있지 않으니 근거를 들어 함께 짐작하면 되겠다.」","scoring_points":["서로 다른 짐작이 드러나는가","짐작마다 근거가 있는가","견주는 태도가 드러나는가"]},"explanation":["다른 짐작이에요.","근거를 들어요.","견주어 봐요."]}'::jsonb),
('g5_2_kor_u5_review_d#1','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C9',1,'ox','auto','근거 없이 떠오르는 대로 지어낸 짐작도 추론이에요.',ARRAY['K5-2-u5-X09']::text[],false,'{"seq":1,"concept":"K5-2-u5-C9","difficulty":1,"kind":"ox","stem":"근거 없이 떠오르는 대로 지어낸 짐작도 추론이에요.","answer":"X","reason_options":[{"t":"추론은 단서나 경험·지식이라는 근거를 바탕으로 하기 때문에","correct":true},{"t":"짐작이면 무엇이든 추론이기 때문에","mis":"K5-2-u5-X09"}],"mis":"K5-2-u5-X09","explanation":["지어낸 것은 추론이 아니에요.","근거가 있어야 해요.","상상과 추론은 달라요."]}'::jsonb),
('g5_2_kor_u5_review_d#2','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C35',1,'mc','auto','「해」와 「쌀」이 어울려 그해에 새로 난 쌀을 뜻하는 낱말은 어느 것인가요?',ARRAY['K5-2-u5-X35']::text[],false,'{"seq":2,"concept":"K5-2-u5-C35","difficulty":1,"kind":"mc","stem":"「해」와 「쌀」이 어울려 그해에 새로 난 쌀을 뜻하는 낱말은 어느 것인가요?","options":[{"t":"햅쌀","correct":true},{"t":"해쌀","mis":"K5-2-u5-X35"},{"t":"햇쌀","mis":"K5-2-u5-X35"},{"t":"햅살","mis":"K5-2-u5-X35"}],"explanation":["ㅂ 소리가 빠졌어요.","받침이 달라요.","ㅂ 소리가 덧나 햅쌀이에요."]}'::jsonb),
('g5_2_kor_u5_review_d#3','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C17',1,'ox','auto','「책은 창문이에요.」처럼 쓰는 것은 틀린 말이라 고쳐야 해요.',ARRAY['K5-2-u5-X17']::text[],false,'{"seq":3,"concept":"K5-2-u5-C17","difficulty":1,"kind":"ox","stem":"「책은 창문이에요.」처럼 쓰는 것은 틀린 말이라 고쳐야 해요.","answer":"X","reason_options":[{"t":"숨은 뜻을 담아 생각을 생생하게 전하는 함축된 표현이기 때문에","correct":true},{"t":"책은 진짜 창문이 아니기 때문에","mis":"K5-2-u5-X17"}],"mis":"K5-2-u5-X17","explanation":["틀린 말이 아니에요.","숨은 뜻이 있어요.","함축된 표현이에요."]}'::jsonb),
