('g5_2_kor_u5_review_d#21','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C27',3,'mc','auto','글쓴이가 비슷한 장면을 되풀이해 쓴 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X27']::text[],false,'{"seq":21,"concept":"K5-2-u5-C27","difficulty":3,"kind":"mc","stem":"글쓴이가 비슷한 장면을 되풀이해 쓴 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"그 장면에 담긴 뜻을 독자가 놓치지 않게 강조하려고","correct":true},{"t":"글자 수를 채우려고","mis":"K5-2-u5-X27"},{"t":"실수로 두 번 썼기 때문에","mis":"K5-2-u5-X27"},{"t":"의도와 관계없이 그냥","mis":"K5-2-u5-X27"}],"explanation":["까닭이 아니에요.","실수가 아니에요.","되풀이는 강조예요."]}'::jsonb),
('g5_2_kor_u5_review_d#22','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C36',3,'mc','auto','「머리카락」, 「안팎」을 소리 나는 대로 적는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X36','K5-2-u5-X35']::text[],false,'{"seq":22,"concept":"K5-2-u5-C36","difficulty":3,"kind":"mc","stem":"「머리카락」, 「안팎」을 소리 나는 대로 적는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 낱말이 어울릴 때 원래 없던 ㅎ 소리가 덧나기 때문에","correct":true},{"t":"원래 낱말 모양 그대로 적어야 하기 때문에","mis":"K5-2-u5-X36"},{"t":"ㅂ 소리가 덧나기 때문에","mis":"K5-2-u5-X35"},{"t":"받침을 빼고 적어야 하기 때문에","mis":"K5-2-u5-X36"}],"explanation":["소리 나는 대로 적어요.","ㅎ 소리예요.","ㅎ 소리가 덧나요."]}'::jsonb),
('g5_2_kor_u5_review_d#23','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C24',4,'essay','teacher','「텃밭의 빈 의자」에서 글쓴이의 의도를 한 문장으로 쓰고, 의도를 짐작하게 한 함축된 표현이나 장면을 두 가지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u5-C24","difficulty":4,"kind":"essay","stem":"「텃밭의 빈 의자」에서 글쓴이의 의도를 한 문장으로 쓰고, 의도를 짐작하게 한 함축된 표현이나 장면을 두 가지 쓰세요.","answer_guide":{"answer":"예: 서로를 생각하는 작은 관심이 사람의 마음을 따뜻하게 한다. 아이들이 「상추가 할아버지를 기다려요.」라고 쪽지를 놓은 장면과, 할아버지가 쪽지를 읽은 날 「비가 그치고 해가 났어요.」라는 마지막 문장이 단서이다.","scoring_points":["의도를 한 문장으로 썼는가","단서 두 가지를 썼는가","단서와 의도가 이어지는가"]},"explanation":["한 문장이에요.","단서 둘이에요.","이어지게 써요."],"asset":{"type":"passage","lines":["학교 텃밭 끝에는 낡은 나무 의자가 하나 있었어요.","경비 할아버지는 날마다 그 의자에 앉아 아이들이 심은 상추를 바라보았어요.","어느 날부터 의자가 비어 있었어요. 할아버지의 모자도 보이지 않았어요.","아이들은 상추에 물을 주며 자꾸 의자 쪽을 돌아보았어요.","며칠 뒤, 의자 위에 아이들이 쓴 쪽지가 하나둘 놓이기 시작했어요.","「할아버지, 상추가 할아버지를 기다려요.」","다시 돌아온 할아버지는 쪽지를 한 장씩 펴 보며 한참 말이 없었어요.","그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요."],"title":"텃밭의 빈 의자"}}'::jsonb),
('g5_2_kor_u5_review_d#24','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C29',4,'essay','teacher','할머니의 마음을 짐작한 두 친구의 말 가운데 더 그럴듯한 쪽을 고르거나 두 생각을 함께 담은 내 짐작을 쓰고, 글 속 근거를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u5-C29","difficulty":4,"kind":"essay","stem":"할머니의 마음을 짐작한 두 친구의 말 가운데 더 그럴듯한 쪽을 고르거나 두 생각을 함께 담은 내 짐작을 쓰고, 글 속 근거를 쓰세요.","answer_guide":{"answer":"예: 할머니는 꽃을 좋아했고, 그 마음이 이웃에게도 번지기를 바랐을 것이다. 날마다 화분을 하나씩 늘린 모습은 꽃을 좋아하는 마음을, 세 해 뒤 이웃들이 따라 화분을 내놓은 장면은 이웃에게 번지기를 바란 마음을 보여 준다.","scoring_points":["짐작을 썼는가","글 속 근거를 썼는가","근거와 짐작이 맞는가"]},"explanation":["짐작해요.","근거를 들어요.","맞는지 살펴요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"할머니는 이웃들이 화분을 따라 내놓기를 바랐을 거야. 이웃들이 따라 했잖아."},{"who":"준서","text":"할머니는 그냥 꽃을 좋아했을 뿐이야. 날마다 화분을 늘렸잖아."}]}}'::jsonb),
('g5_2_kor_u5_review_d#25','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C32',4,'essay','teacher','감정 카드 활동을 한다면 친구의 카드를 보고 마음을 짐작하고 확인하고 공감하는 차례를 쓰고, 각 차례에서 할 말을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u5-C32","difficulty":4,"kind":"essay","stem":"감정 카드 활동을 한다면 친구의 카드를 보고 마음을 짐작하고 확인하고 공감하는 차례를 쓰고, 각 차례에서 할 말을 쓰세요.","answer_guide":{"answer":"예: 짐작하기 — 「마음에 먹구름이 끼었다니 속상한 일이 있었나 봐.」 확인하기 — 「혹시 속상한 일이 있었어? 내 짐작이 맞아?」 공감하기 — 「그런 일이 있었구나. 많이 속상했겠다. 내가 곁에 있을게.」","scoring_points":["짐작·확인·공감의 차례를 썼는가","차례마다 할 말을 썼는가","친구를 존중하는 말인가"]},"explanation":["세 차례예요.","할 말을 써요.","존중해요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('K5-2-u6-C1','kor',5,2,'u6',1,'깊이 있게 감상하기 — 줄거리만 아는 데서 그치지 않고 누가, 언제, 어디에서, 어떤 일을 겪는지와 인물의 성격까지 살피며 작품의 의미를 생각한다',ARRAY['6국05-03 문학']::text[],1),
('K5-2-u6-C2','kor',5,2,'u6',1,'작품을 소개할 때 담을 것 — 주인공과 줄거리에 더해 인물의 성격, 이야기가 펼쳐지는 때와 곳, 일이 흘러가는 모습을 함께 담으면 전체 흐름이 보인다',ARRAY['6국05-03 문학']::text[],2),
('K5-2-u6-C3','kor',5,2,'u6',1,'연극과 인형극 — 사람이 맡든 인형이 맡든 등장인물과 무대가 있고, 공연하려면 무대에서 할 말과 움직임을 적은 극본이 있어야 한다',ARRAY['6국05-03 문학']::text[],3),
('K5-2-u6-C4','kor',5,2,'u6',1,'단원의 흐름 — 이야기의 구성 요소 → 이야기 감상 → 극본의 구성 요소 → 극본 감상 → 연극하기 → 감상 질문으로 실천하기',ARRAY['6국05-03 문학']::text[],4),
('K5-2-u6-C5','kor',5,2,'u6',2,'인물 — 이야기에서 어떤 일을 겪는 사람이나 사물로, 동물이나 물건도 인물이 될 수 있다',ARRAY['6국05-03 문학']::text[],5),
('K5-2-u6-C6','kor',5,2,'u6',2,'사건 — 이야기에서 일어나는 일로, 일어난 차례대로 살피면 흐름이 보인다',ARRAY['6국05-03 문학']::text[],6),
('K5-2-u6-C7','kor',5,2,'u6',2,'배경 — 이야기가 펼쳐지는 시간과 장소, 사회적 상황',ARRAY['6국05-03 문학']::text[],7),
('K5-2-u6-C8','kor',5,2,'u6',2,'시대적 배경 — 일이 언제, 어떤 시대와 상황에서 일어났는지를 말한다',ARRAY['6국05-03 문학']::text[],8),
('K5-2-u6-C9','kor',5,2,'u6',2,'공간적 배경 — 일이 어디에서 일어났는지를 말한다',ARRAY['6국05-03 문학']::text[],9),
('K5-2-u6-C10','kor',5,2,'u6',2,'말과 행동으로 성격 알기 — 인물의 말과 행동을 근거로 인물의 성격을 짐작한다',ARRAY['6국05-03 문학']::text[],10),
('K5-2-u6-C11','kor',5,2,'u6',2,'배경이 사건에 주는 영향 — 배경은 장식이 아니라 사건을 만들고 인물의 마음에 영향을 준다',ARRAY['6국05-03 문학']::text[],11),
('K5-2-u6-C12','kor',5,2,'u6',2,'구성 요소를 생각하며 읽기 — 인물, 사건, 배경을 생각하며 읽으면 이야기의 전체 흐름과 의미를 잘 파악할 수 있다',ARRAY['6국05-03 문학']::text[],12),
('K5-2-u6-C13','kor',5,2,'u6',4,'사건에 따라 바뀌는 마음 — 사건이 바뀔 때마다 인물의 마음이 어떻게 달라지는지 차례대로 따라가며 읽는다',ARRAY['6국05-03 문학']::text[],13),
('K5-2-u6-C14','kor',5,2,'u6',4,'배경·사건·마음의 이어짐 — 배경이 사건을 만들고 사건이 인물의 마음을 바꾸는 이어짐을 살피며 감상한다',ARRAY['6국05-03 문학']::text[],14),
('K5-2-u6-C15','kor',5,2,'u6',4,'말 뒤에 숨은 행동의 마음 — 짧고 무뚝뚝한 말 뒤에도 행동에 깊은 마음이 담길 수 있어 말과 행동을 함께 본다',ARRAY['6국05-03 문학']::text[],15),
('K5-2-u6-C16','kor',5,2,'u6',4,'모르는 낱말의 뜻 알기 — 앞뒤 문장으로 짐작하고 국어사전에서 확인한 뒤 찾은 뜻을 문장에 넣어 읽어 본다',ARRAY['6국05-03 문학']::text[],16),
('K5-2-u6-C17','kor',5,2,'u6',4,'이야기 속 낱말 — 들뜨다 · 묵묵히 · 야속하다 · 잦아들다처럼 이야기 속 낱말의 뜻을 알면 인물의 마음과 장면이 또렷해진다',ARRAY['6국05-03 문학']::text[],17),
('K5-2-u6-C18','kor',5,2,'u6',4,'인상 깊은 장면 — 인상 깊은 장면은 사람마다 다를 수 있고, 고른 까닭을 이야기 속 근거와 함께 말한다',ARRAY['6국05-04 문학']::text[],18),
('K5-2-u6-C19','kor',5,2,'u6',4,'인물에게 편지 쓰기 — 인물이 겪은 일과 그때의 마음을 헤아려 내 마음을 담아 쓰면 감상을 표현할 수 있다',ARRAY['6국05-04 문학']::text[],19),
('K5-2-u6-C20','kor',5,2,'u6',7,'극본 — 연극을 하려고 쓴 글',ARRAY['6국05-03 문학']::text[],20),
('K5-2-u6-C21','kor',5,2,'u6',7,'해설 — 대체로 극본의 첫 부분에서 때, 곳, 등장인물, 무대 배경 같은 것을 설명하는 부분으로, 인물의 감정을 알려 주지는 않는다',ARRAY['6국05-03 문학']::text[],21),
('K5-2-u6-C22','kor',5,2,'u6',7,'대사 — 극본에서 인물이 직접 하는 말',ARRAY['6국05-03 문학']::text[],22),
('K5-2-u6-C23','kor',5,2,'u6',7,'지문 — 인물의 표정, 행동, 말투 같은 것을 설명하려고 괄호로 나타낸 부분으로, 소리 내어 말하지 않고 몸과 목소리로 표현한다',ARRAY['6국05-03 문학']::text[],23),
('K5-2-u6-C24','kor',5,2,'u6',7,'이야기 글과 극본 — 이야기 글은 줄글로 읽는 사람에게 들려주고, 극본은 공연하려고 대사와 지문으로 나누어 쓴다',ARRAY['6국05-03 문학']::text[],24),
('K5-2-u6-C25','kor',5,2,'u6',7,'극본 낭독하기 — 역할을 나누어 해설부터 차례대로 읽고, 지문을 보고 알맞은 목소리와 표정으로 대사를 한다',ARRAY['6국05-03 문학']::text[],25),
('K5-2-u6-C26','kor',5,2,'u6',7,'장면을 상상하며 읽기 — 해설과 지문을 보고 무대 위 장면과 인물의 움직임을 떠올리며 극본을 읽는다',ARRAY['6국05-03 문학']::text[],26),
('K5-2-u6-C27','kor',5,2,'u6',9,'해설·대사·지문 이어 읽기 — 대사만이 아니라 해설·대사·지문을 이어 읽어야 사건의 흐름과 인물의 마음을 제대로 감상할 수 있다',ARRAY['6국05-03 문학']::text[],27),
('K5-2-u6-C28','kor',5,2,'u6',9,'인물 관계도 — 누가 누구와 어떤 사이인지 한눈에 보여 주고, 대사를 어떤 마음과 목소리로 할지 짐작하게 한다',ARRAY['6국05-03 문학']::text[],28),
('K5-2-u6-C29','kor',5,2,'u6',9,'사건의 차례와 흐름을 바꾼 사건 — 사건을 일어난 차례대로 정리하면 흐름이 보이고, 뜻밖의 사건이 흐름을 바꾸기도 한다',ARRAY['6국05-03 문학']::text[],29),
('K5-2-u6-C30','kor',5,2,'u6',9,'역할 수행 학습의 차례 — 상황 설정하기 → 준비 및 연습하기 → 실연하기 → 평가하기',ARRAY['6국05-03 문학']::text[],30),
('K5-2-u6-C31','kor',5,2,'u6',9,'맡은 인물에게 묻기 — 「이 인물은 왜 이렇게 말했을까?」를 물으면 그 순간 인물의 마음을 깊이 이해할 수 있다',ARRAY['6국05-04 문학']::text[],31),
('K5-2-u6-C32','kor',5,2,'u6',9,'인상적인 부분 나누기 — 극본에서 인상적인 부분을 고르고 대사·지문 같은 근거와 까닭을 들어 나눈다',ARRAY['6국05-04 문학']::text[],32),
('K5-2-u6-C33','kor',5,2,'u6',11,'연극 준비의 차례 — 장면 정하기 → 인물의 특징을 살펴 역할 정하기 → 소품 준비하기 → 연습하기 → 점검하기',ARRAY['6국05-04 문학']::text[],33),
('K5-2-u6-C34','kor',5,2,'u6',11,'인물의 특징을 살린 표현 — 같은 대사도 인물의 성격과 지문, 그 순간의 마음에 따라 목소리·표정·몸짓이 달라진다',ARRAY['6국05-04 문학']::text[],34),
('K5-2-u6-C35','kor',5,2,'u6',11,'연극 전 점검 — 소품, 등장 순서, 흐름이 어색한 부분, 또렷한 말소리를 미리 확인한다',ARRAY['6국05-04 문학']::text[],35),
('K5-2-u6-C36','kor',5,2,'u6',11,'연극을 하는 까닭 — 대사를 틀리지 않고 외워 보여 주기보다 작품을 깊이 감상한 것을 인물의 마음이 드러나게 표현하는 것이 중요하다',ARRAY['6국05-04 문학']::text[],36),
('K5-2-u6-C37','kor',5,2,'u6',11,'협력하고 되돌아보기 — 여럿이 협력해 맡은 역할에 책임을 다하고, 목소리·몸짓·협력을 기준으로 잘한 점부터 나눈다',ARRAY['6국05-04 문학']::text[],37),
('K5-2-u6-C38','kor',5,2,'u6',13,'감상 질문 — 답이 하나로 정해져 있지 않고 인물의 마음, 사건의 의미, 배경의 영향을 깊이 생각하게 하는 질문',ARRAY['6국05-03 문학']::text[],38),
('K5-2-u6-C39','kor',5,2,'u6',13,'구성 요소로 감상 질문 만들기 — 인물, 사건, 배경을 하나씩 떠올리며 「왜?」, 「어떤 의미일까?」로 묻는다',ARRAY['6국05-03 문학']::text[],39),
('K5-2-u6-C40','kor',5,2,'u6',13,'묻고 답하며 감상 나누기 — 근거를 들어 답하고 다른 생각도 끝까지 들으며, 나누기 전과 뒤에 달라진 내 감상을 살핀다',ARRAY['6국02-05 읽기']::text[],40),
('K5-2-u6-C41','kor',5,2,'u6',13,'함께 할 감상 활동 정하기 — 구성 요소를 생각하며 감상하는 활동을 고르고 반 전체·모둠·짝·혼자 가운데 방법을 모두의 의견으로 정한다',ARRAY['6국02-05 읽기']::text[],41),
('K5-2-u6-C42','kor',5,2,'u6',15,'높임 어휘로 직접 높이기 — 웃어른을 직접 높일 때 높임 어휘가 있으면 그것을 먼저 쓴다 — 계시다 · 편찮으시다 (기초 다지기)',ARRAY['기초 다지기(높임 표현)']::text[],42),
('K5-2-u6-C43','kor',5,2,'u6',15,'있으시다 — 웃어른과 밀접한 대상(말씀 · 고민 · 생각)을 높일 때에는 「계시다」가 아니라 「있으시다」를 쓴다 (기초 다지기)',ARRAY['기초 다지기(높임 표현)']::text[],43)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('K5-2-u6-X01','kor',5,'u6',ARRAY['K5-2-u6-C1']::text[],'작품을 감상한다는 것을 줄거리를 아는 것으로만 여긴다','때·곳·인물까지'),
('K5-2-u6-X02','kor',5,'u6',ARRAY['K5-2-u6-C2']::text[],'이야기를 소개할 때 주인공 이름과 줄거리만 쓰면 충분하다고 여기거나 내용과 관계없는 것을 담는다','성격·때·곳도 함께'),
('K5-2-u6-X03','kor',5,'u6',ARRAY['K5-2-u6-C3']::text[],'인형극은 사람 배우가 없으니 등장인물이나 극본이 없다고 여긴다','인형도 인물을 맡아요'),
('K5-2-u6-X04','kor',5,'u6',ARRAY['K5-2-u6-C4']::text[],'단원에서 배우는 차례를 섞거나 배울 내용과 하는 일을 엇갈리게 잇는다','이야기 → 극본 → 연극'),
('K5-2-u6-X05','kor',5,'u6',ARRAY['K5-2-u6-C5']::text[],'인물은 사람만 될 수 있다고 여기거나 인물을 때·곳·일과 헷갈린다','일을 겪는 사람이나 사물'),
('K5-2-u6-X06','kor',5,'u6',ARRAY['K5-2-u6-C6']::text[],'사건을 인물이나 배경과 헷갈리거나 일어난 일을 차례 없이 늘어놓는다','일어나는 일'),
('K5-2-u6-X07','kor',5,'u6',ARRAY['K5-2-u6-C7']::text[],'배경을 장소만으로 여겨 시간이나 사회적 상황은 배경이 아니라고 여긴다','시간·장소·사회적 상황'),
('K5-2-u6-X08','kor',5,'u6',ARRAY['K5-2-u6-C8']::text[],'시대적 배경을 묻는데 장소를 고르거나 때를 알려 주는 말을 찾지 못한다','언제 · 어떤 시대'),
('K5-2-u6-X09','kor',5,'u6',ARRAY['K5-2-u6-C9']::text[],'공간적 배경을 묻는데 때나 시대를 고른다','어디에서'),
('K5-2-u6-X10','kor',5,'u6',ARRAY['K5-2-u6-C10']::text[],'말과 행동을 살피지 않고 근거 없이 인물의 성격을 정한다','말과 행동이 근거'),
('K5-2-u6-X11','kor',5,'u6',ARRAY['K5-2-u6-C11']::text[],'배경은 이야기의 장식일 뿐이라 사건이나 인물의 마음과 관계없다고 여긴다','배경이 사건을 만들어요'),
('K5-2-u6-X12','kor',5,'u6',ARRAY['K5-2-u6-C12']::text[],'구성 요소를 따지는 것은 외우기일 뿐 이야기를 이해하는 데 도움이 되지 않는다고 여기거나 구성 요소를 잘못 모은다','흐름과 의미가 보여요'),
('K5-2-u6-X13','kor',5,'u6',ARRAY['K5-2-u6-C13']::text[],'인물의 마음이 처음부터 끝까지 같다고 여기거나 마음의 변화를 차례 없이 늘어놓는다','사건마다 달라져요'),
('K5-2-u6-X14','kor',5,'u6',ARRAY['K5-2-u6-C14']::text[],'배경, 사건, 인물의 마음을 따로따로만 보고 서로 이어진 관계를 살피지 않는다','배경 → 사건 → 마음'),
('K5-2-u6-X15','kor',5,'u6',ARRAY['K5-2-u6-C15']::text[],'인물의 말만 보고 마음을 판단해 행동에 담긴 마음을 놓친다','행동도 함께 봐요'),
('K5-2-u6-X16','kor',5,'u6',ARRAY['K5-2-u6-C16']::text[],'모르는 낱말을 그냥 지나치거나 사전 뜻을 베끼기만 하고 문장에 넣어 확인하지 않는다','짐작 → 사전 → 넣어 읽기'),
('K5-2-u6-X17','kor',5,'u6',ARRAY['K5-2-u6-C17']::text[],'이야기 속 낱말의 뜻을 앞뒤 문장과 반대로 짐작한다','앞뒤 문장을 봐요'),
('K5-2-u6-X18','kor',5,'u6',ARRAY['K5-2-u6-C18']::text[],'인상 깊은 장면은 하나로 정해져 있다고 여기거나 까닭 없이 장면만 고른다','사람마다 · 까닭과 함께'),
('K5-2-u6-X19','kor',5,'u6',ARRAY['K5-2-u6-C19']::text[],'인물에게 편지를 쓸 때 인물의 처지나 마음은 헤아리지 않고 줄거리만 옮기거나 꾸짖기만 한다','겪은 일과 마음을 헤아려'),
('K5-2-u6-X20','kor',5,'u6',ARRAY['K5-2-u6-C20']::text[],'극본을 혼자 줄글로 읽으려고 쓴 글로 여긴다','연극을 하려고 쓴 글'),
('K5-2-u6-X21','kor',5,'u6',ARRAY['K5-2-u6-C21']::text[],'해설을 보면 인물의 감정을 알 수 있다고 여기거나 해설을 대사·지문과 헷갈린다','때·곳·인물·무대'),
('K5-2-u6-X22','kor',5,'u6',ARRAY['K5-2-u6-C22']::text[],'인물이 직접 하는 말(대사)을 해설이나 지문과 헷갈린다','인물이 직접 하는 말'),
('K5-2-u6-X23','kor',5,'u6',ARRAY['K5-2-u6-C23']::text[],'괄호 안의 지문도 배우가 소리 내어 말하는 대사라고 여기거나 지문을 해설과 헷갈린다','몸과 목소리로 표현'),
('K5-2-u6-X24','kor',5,'u6',ARRAY['K5-2-u6-C24']::text[],'이야기 글과 극본의 쓰는 방법과 목적을 헷갈려 극본에도 인물의 말을 줄글로 이어 쓴다','대사와 지문으로 나눠요'),
('K5-2-u6-X25','kor',5,'u6',ARRAY['K5-2-u6-C25']::text[],'극본을 낭독할 때 지문을 살피지 않고 모든 대사를 같은 목소리로 읽거나 해설을 빼고 읽는다','지문대로 목소리를'),
('K5-2-u6-X26','kor',5,'u6',ARRAY['K5-2-u6-C26']::text[],'극본을 읽을 때 무대 위 장면은 떠올리지 않고 글자만 따라 읽는다','장면을 상상해요'),
('K5-2-u6-X27','kor',5,'u6',ARRAY['K5-2-u6-C27']::text[],'극본은 대사만 따라 읽으면 내용을 다 알 수 있다고 여긴다','해설·대사·지문 이어서'),
('K5-2-u6-X28','kor',5,'u6',ARRAY['K5-2-u6-C28']::text[],'인물 관계도에 관계를 잘못 잇거나 관계가 바뀌는 모습을 놓친다','어떤 사이인지 자세히'),
('K5-2-u6-X29','kor',5,'u6',ARRAY['K5-2-u6-C29']::text[],'사건을 일어난 차례와 다르게 늘어놓거나 흐름을 바꾼 사건을 찾지 못한다','일어난 차례대로'),
('K5-2-u6-X30','kor',5,'u6',ARRAY['K5-2-u6-C30']::text[],'역할 수행 학습의 차례를 섞어 준비 없이 실연부터 하거나 평가를 빼놓는다','설정 → 연습 → 실연 → 평가'),
('K5-2-u6-X31','kor',5,'u6',ARRAY['K5-2-u6-C31']::text[],'맡은 인물의 대사를 외우기만 하고 인물이 왜 그렇게 말했는지는 묻지 않는다','왜 그렇게 말했을까'),
('K5-2-u6-X32','kor',5,'u6',ARRAY['K5-2-u6-C32']::text[],'인상적인 부분을 말할 때 극본 속 근거나 까닭 없이 「재미있다」로만 말하거나 내 까닭만 맞다고 우긴다','근거와 까닭'),
('K5-2-u6-X33','kor',5,'u6',ARRAY['K5-2-u6-C33']::text[],'인물의 특징을 살피지 않고 역할부터 정하거나 연극 준비의 차례를 뒤섞는다','인물 특징부터'),
('K5-2-u6-X34','kor',5,'u6',ARRAY['K5-2-u6-C34']::text[],'같은 대사는 인물이나 상황이 달라도 늘 같은 목소리로 표현하면 된다고 여긴다','성격·지문·마음 따라'),
('K5-2-u6-X35','kor',5,'u6',ARRAY['K5-2-u6-C35']::text[],'연극하기 전에 소품이나 등장 순서를 점검하지 않거나 점검과 관계없는 것을 챙긴다','소품 · 순서 · 흐름'),
('K5-2-u6-X36','kor',5,'u6',ARRAY['K5-2-u6-C36']::text[],'연극은 대사를 하나도 틀리지 않고 외워서 보여 주는 것이 가장 중요하다고 여긴다','감상한 것을 표현'),
('K5-2-u6-X37','kor',5,'u6',ARRAY['K5-2-u6-C37']::text[],'연극을 되돌아볼 때 아쉬운 점만 늘어놓거나 잘하는 친구에게만 역할을 몰아준다','협력 · 잘한 점 먼저'),
('K5-2-u6-X38','kor',5,'u6',ARRAY['K5-2-u6-C38']::text[],'감상 질문은 이야기에 답이 그대로 쓰여 있는 것을 묻는 것이 좋다고 여긴다','답이 여럿인 질문'),
('K5-2-u6-X39','kor',5,'u6',ARRAY['K5-2-u6-C39']::text[],'감상 질문을 만들 때 인물·사건·배경 가운데 어느 요소에 대한 질문인지 가르지 못한다','인물 · 사건 · 배경'),
('K5-2-u6-X40','kor',5,'u6',ARRAY['K5-2-u6-C40']::text[],'감상을 나눌 때 내 답만 맞다고 우기거나 근거 없이 느낌만 말한다','근거 · 끝까지 듣기'),
('K5-2-u6-X41','kor',5,'u6',ARRAY['K5-2-u6-C41']::text[],'함께 할 활동을 목소리 큰 친구의 뜻대로만 정하거나 감상과 관계없는 활동을 고른다','모두의 의견으로'),
('K5-2-u6-X42','kor',5,'u6',ARRAY['K5-2-u6-C42']::text[],'웃어른을 직접 높일 때 높임 어휘를 두고 「있으시다」, 「아프시다」처럼 쓴다','계시다 · 편찮으시다'),
('K5-2-u6-X43','kor',5,'u6',ARRAY['K5-2-u6-C43']::text[],'웃어른과 관련된 말이면 말씀이나 고민에도 「계시다」를 쓴다','말씀 · 고민엔 있으시다')
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g5_2_kor_u6_L01_basic#1','kor',5,2,'u6','L01','g5_2_kor_u6_L01_basic','lesson_basic','K5-2-u6-C1',1,'mc','auto','책 소개 메모에 쓰여 있는 내용은 어느 것인가요?',ARRAY['K5-2-u6-X02']::text[],false,'{"seq":1,"concept":"K5-2-u6-C1","difficulty":1,"kind":"mc","stem":"책 소개 메모에 쓰여 있는 내용은 어느 것인가요?","options":[{"t":"주인공 바다는 등대섬에 산다","correct":true},{"t":"바다는 겁이 많은 아이이다","mis":"K5-2-u6-X02"},{"t":"이야기는 겨울에 펼쳐진다","mis":"K5-2-u6-X02"},{"t":"바다는 할아버지의 손녀이다","mis":"K5-2-u6-X02"}],"explanation":["메모에 성격은 없어요.","메모에 계절은 없어요.","주인공과 사는 곳은 쓰여 있어요."],"asset":{"type":"passage","lines":["책 제목: 「등대섬의 여름」","주인공: 등대섬에 사는 소녀 바다","줄거리: 바다는 폭풍이 몰아치는 밤, 등대지기 할아버지를 도와 등대 불을 지킨다.","소개하고 싶은 까닭: 마지막 장면이 오래 기억에 남는다."],"title":"책 소개 메모"}}'::jsonb),
('g5_2_kor_u6_L01_basic#2','kor',5,2,'u6','L01','g5_2_kor_u6_L01_basic','lesson_basic','K5-2-u6-C2',1,'mc','auto','책 소개 메모에 더 담으면 이야기를 깊이 알 수 있는 것은 어느 것인가요?',ARRAY['K5-2-u6-X02']::text[],false,'{"seq":2,"concept":"K5-2-u6-C2","difficulty":1,"kind":"mc","stem":"책 소개 메모에 더 담으면 이야기를 깊이 알 수 있는 것은 어느 것인가요?","options":[{"t":"이야기가 언제, 어디에서 펼쳐지는지","correct":true},{"t":"책이 모두 몇 쪽인지","mis":"K5-2-u6-X02"},{"t":"책값이 얼마인지","mis":"K5-2-u6-X02"},{"t":"책 표지가 무슨 색인지","mis":"K5-2-u6-X02"}],"explanation":["내용과 거리가 멀어요.","내용과 거리가 멀어요.","때와 곳을 알면 흐름이 보여요."],"asset":{"type":"passage","lines":["책 제목: 「등대섬의 여름」","주인공: 등대섬에 사는 소녀 바다","줄거리: 바다는 폭풍이 몰아치는 밤, 등대지기 할아버지를 도와 등대 불을 지킨다.","소개하고 싶은 까닭: 마지막 장면이 오래 기억에 남는다."],"title":"책 소개 메모"}}'::jsonb),
('g5_2_kor_u6_L01_basic#3','kor',5,2,'u6','L01','g5_2_kor_u6_L01_basic','lesson_basic','K5-2-u6-C3',1,'ox','auto','연극과 인형극에는 모두 등장인물과 무대가 있어요.',ARRAY['K5-2-u6-X03']::text[],false,'{"seq":3,"concept":"K5-2-u6-C3","difficulty":1,"kind":"ox","stem":"연극과 인형극에는 모두 등장인물과 무대가 있어요.","answer":"O","reason_options":[{"t":"인형극에서는 인형이 인물을 맡을 뿐 등장인물과 무대가 있기 때문에","correct":true},{"t":"인형극에는 사람 배우가 없어 등장인물이 없기 때문에","mis":"K5-2-u6-X03"}],"mis":"K5-2-u6-X03","explanation":["인형도 인물을 맡아요.","둘 다 무대가 있어요.","둘의 같은 점이에요."]}'::jsonb),
