('g5_2_kor_u6_review_a#4','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C9',1,'mc','auto','「골목 끝 수선집」의 공간적 배경은 어느 것인가요?',ARRAY['K5-2-u6-X09']::text[],false,'{"seq":4,"concept":"K5-2-u6-C9","difficulty":1,"kind":"mc","stem":"「골목 끝 수선집」의 공간적 배경은 어느 것인가요?","options":[{"t":"시장 골목 끝의 작은 신발 수선집","correct":true},{"t":"눈이 펑펑 내리던 겨울","mis":"K5-2-u6-X09"},{"t":"달리기 대회 날","mis":"K5-2-u6-X09"},{"t":"다음 날 아침","mis":"K5-2-u6-X09"}],"explanation":["때예요.","때예요.","어디에서인지가 공간적 배경이에요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb),
('g5_2_kor_u6_review_a#5','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C26',1,'mc','auto','「도서관의 마지막 손님」의 해설을 보고 떠올릴 수 있는 무대는 어느 것인가요?',ARRAY['K5-2-u6-X26']::text[],false,'{"seq":5,"concept":"K5-2-u6-C26","difficulty":1,"kind":"mc","stem":"「도서관의 마지막 손님」의 해설을 보고 떠올릴 수 있는 무대는 어느 것인가요?","options":[{"t":"불빛이 하나둘 꺼지는 책장 사이와 빗방울 맺힌 창문","correct":true},{"t":"햇빛이 쏟아지는 운동장","mis":"K5-2-u6-X26"},{"t":"눈 덮인 산골 우체국","mis":"K5-2-u6-X26"},{"t":"숲속 빈터의 나무 무대","mis":"K5-2-u6-X26"}],"explanation":["해설과 달라요.","다른 극본이에요.","해설로 무대를 떠올려요."],"asset":{"type":"passage","lines":["때: 비 오는 토요일 저녁 · 곳: 동네 작은 도서관 · 나오는 인물: 지안, 사서 선생님","책장 사이로 불빛이 하나둘 꺼지고, 창문에 빗방울이 맺혀 있다.","사서 선생님: (열쇠 꾸러미를 흔들며) 지안아, 이제 문 닫을 시간이란다.","지안: (책을 품에 꼭 안으며) 딱 한 장만 더 읽으면 안 돼요? 주인공이 곧 집에 돌아가거든요.","사서 선생님: (잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.","지안: (눈을 동그랗게 뜨고) 정말요? (책장을 넘기며 작은 소리로 읽기 시작한다.)"],"title":"극본 「도서관의 마지막 손님」"}}'::jsonb),
