('g5_2_kor_u6_review_a#21','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C30',3,'mc','auto','역할 수행 학습의 실연하기에서 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X30']::text[],false,'{"seq":21,"concept":"K5-2-u6-C30","difficulty":3,"kind":"mc","stem":"역할 수행 학습의 실연하기에서 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"맡은 역할이 되어 극본을 낭독하거나 연기한다","correct":true},{"t":"학습 문제를 확인한다","mis":"K5-2-u6-X30"},{"t":"사건 차례를 정리한다","mis":"K5-2-u6-X30"},{"t":"인상적인 부분을 되돌아본다","mis":"K5-2-u6-X30"}],"explanation":["상황 설정하기예요.","준비 및 연습하기예요.","실연은 역할이 되어 해 보는 거예요."]}'::jsonb),
('g5_2_kor_u6_review_a#22','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C18',3,'mc','auto','「골목 끝 수선집」에서 두 친구가 서로 다른 장면을 인상 깊다고 했어요. 알맞은 생각은 어느 것인가요?',ARRAY['K5-2-u6-X18']::text[],false,'{"seq":22,"concept":"K5-2-u6-C18","difficulty":3,"kind":"mc","stem":"「골목 끝 수선집」에서 두 친구가 서로 다른 장면을 인상 깊다고 했어요. 알맞은 생각은 어느 것인가요?","options":[{"t":"고른 까닭이 이야기와 맞으면 서로 다른 장면을 골라도 된다","correct":true},{"t":"인상 깊은 장면은 하나로 정해져 있다","mis":"K5-2-u6-X18"},{"t":"까닭은 말하지 않아도 된다","mis":"K5-2-u6-X18"},{"t":"더 많은 친구가 고른 장면만 맞다","mis":"K5-2-u6-X18"}],"explanation":["사람마다 달라요.","까닭이 필요해요.","근거가 맞으면 돼요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb),
('g5_2_kor_u6_review_a#23','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C7',4,'essay','teacher','「골목 끝 수선집」의 인물, 사건, 배경을 정리해 쓰고, 배경이 사건과 인물의 마음에 어떤 영향을 주었는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u6-C7","difficulty":4,"kind":"essay","stem":"「골목 끝 수선집」의 인물, 사건, 배경을 정리해 쓰고, 배경이 사건과 인물의 마음에 어떤 영향을 주었는지 쓰세요.","answer_guide":{"answer":"예: 인물 — 서준, 수선집 할아버지. 사건 — 달리기 대회 전날 밑창이 떨어진 운동화를 할아버지가 고쳐 주고 「끝까지」라는 글씨를 새겨 주었다. 배경 — 눈이 펑펑 내리던 겨울, 시장 골목 끝 작은 수선집. 대회 바로 전날이라는 때가 서준이를 급하게 만들었고, 눈 내리는 골목 끝 작은 수선집이라는 곳은 할아버지의 말없는 따뜻함을 더 크게 느끼게 한다.","scoring_points":["인물·사건·배경을 정리했는가","배경이 사건에 준 영향을 썼는가","인물의 마음과 이어 썼는가"]},"explanation":["정리해요.","사건과 이어요.","마음과 이어요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb),
('g5_2_kor_u6_review_a#24','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C24',4,'essay','teacher','「골목 끝 수선집」에서 서준이가 수선집에 들어서는 장면을 해설, 대사, 지문이 들어간 극본으로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u6-C24","difficulty":4,"kind":"essay","stem":"「골목 끝 수선집」에서 서준이가 수선집에 들어서는 장면을 해설, 대사, 지문이 들어간 극본으로 바꾸어 쓰세요.","answer_guide":{"answer":"예: 때: 눈 내리는 겨울 저녁 · 곳: 시장 골목 끝 작은 신발 수선집 · 나오는 인물: 서준, 할아버지 / 할아버지가 안경을 코끝에 걸치고 바느질을 한다. / 서준: (운동화를 들고 쭈뼛쭈뼛 들어서며) 저……. 내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요. / 할아버지: (운동화를 이리저리 돌려 보다가 말없이 고개를 끄덕인다.)","scoring_points":["해설을 썼는가","대사를 인물 이름 뒤에 썼는가","지문을 괄호로 썼는가"]},"explanation":["해설을 써요.","대사로 써요.","지문은 괄호로 써요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb),
('g5_2_kor_u6_review_a#25','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C42',4,'essay','teacher','웃어른께 높임 표현을 바르게 쓴 문장을 두 개 만들어 쓰세요. 하나는 「계시다」나 「편찮으시다」처럼 어른을 직접 높이는 말을, 하나는 「있으시다」처럼 어른과 밀접한 대상을 높이는 말을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u6-C42","difficulty":4,"kind":"essay","stem":"웃어른께 높임 표현을 바르게 쓴 문장을 두 개 만들어 쓰세요. 하나는 「계시다」나 「편찮으시다」처럼 어른을 직접 높이는 말을, 하나는 「있으시다」처럼 어른과 밀접한 대상을 높이는 말을 쓰세요.","answer_guide":{"answer":"예: 할아버지께서 거실에 계십니다. 선생님께서는 우리 반에 하실 말씀이 있으십니다.","scoring_points":["어른을 직접 높이는 문장을 썼는가","밀접한 대상을 높이는 문장을 썼는가","높임 표현이 바른가"]},"explanation":["직접 높여요.","밀접한 대상을 높여요.","바르게 써요."],"asset":{"type":"passage","lines":["할머니께서 아프십니다. → 할머니께서 편찮으십니다.","할아버지께서는 고민이 계십니다. → 할아버지께서는 고민이 있으십니다.","교장 선생님께서 교장실에 있으십니다. → 교장 선생님께서 교장실에 계십니다.","교장 선생님의 말씀이 계시겠습니다. → 교장 선생님의 말씀이 있으시겠습니다."],"title":"높임 표현 바르게 고치기"}}'::jsonb),
('g5_2_kor_u6_review_b#1','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C7',1,'ox','auto','이야기가 펼쳐지는 시간과 장소, 사회적 상황을 배경이라고 해요.',ARRAY['K5-2-u6-X07']::text[],false,'{"seq":1,"concept":"K5-2-u6-C7","difficulty":1,"kind":"ox","stem":"이야기가 펼쳐지는 시간과 장소, 사회적 상황을 배경이라고 해요.","answer":"O","reason_options":[{"t":"배경은 이야기가 언제, 어디에서, 어떤 상황에서 펼쳐지는지를 말하기 때문에","correct":true},{"t":"배경은 이야기가 펼쳐지는 장소만을 말하기 때문에","mis":"K5-2-u6-X07"}],"mis":"K5-2-u6-X07","explanation":["때도 배경이에요.","상황도 배경이에요.","배경의 뜻이에요."]}'::jsonb),
('g5_2_kor_u6_review_b#2','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C23',1,'mc','auto','「도서관의 마지막 손님」에서 지문을 찾으면 어느 것인가요?',ARRAY['K5-2-u6-X23','K5-2-u6-X22','K5-2-u6-X21']::text[],false,'{"seq":2,"concept":"K5-2-u6-C23","difficulty":1,"kind":"mc","stem":"「도서관의 마지막 손님」에서 지문을 찾으면 어느 것인가요?","options":[{"t":"(책을 품에 꼭 안으며)","correct":true},{"t":"딱 한 장만 더 읽으면 안 돼요?","mis":"K5-2-u6-X23"},{"t":"그럼 나도 같이 기다릴게.","mis":"K5-2-u6-X22"},{"t":"때: 비 오는 토요일 저녁","mis":"K5-2-u6-X21"}],"explanation":["대사예요.","대사예요.","괄호 속 행동이 지문이에요."],"asset":{"type":"passage","lines":["때: 비 오는 토요일 저녁 · 곳: 동네 작은 도서관 · 나오는 인물: 지안, 사서 선생님","책장 사이로 불빛이 하나둘 꺼지고, 창문에 빗방울이 맺혀 있다.","사서 선생님: (열쇠 꾸러미를 흔들며) 지안아, 이제 문 닫을 시간이란다.","지안: (책을 품에 꼭 안으며) 딱 한 장만 더 읽으면 안 돼요? 주인공이 곧 집에 돌아가거든요.","사서 선생님: (잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.","지안: (눈을 동그랗게 뜨고) 정말요? (책장을 넘기며 작은 소리로 읽기 시작한다.)"],"title":"극본 「도서관의 마지막 손님」"}}'::jsonb),
('g5_2_kor_u6_review_b#3','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C43',1,'mc','auto','「할아버지께서는 고민이 계십니다.」를 바르게 고친 것은 어느 것인가요?',ARRAY['K5-2-u6-X43']::text[],false,'{"seq":3,"concept":"K5-2-u6-C43","difficulty":1,"kind":"mc","stem":"「할아버지께서는 고민이 계십니다.」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"할아버지께서는 고민이 있으십니다.","correct":true},{"t":"할아버지께서는 고민이 계시겠습니다.","mis":"K5-2-u6-X43"},{"t":"할아버지께서는 고민이 계셨습니다.","mis":"K5-2-u6-X43"},{"t":"할아버지께서는 고민께서 계십니다.","mis":"K5-2-u6-X43"}],"explanation":["고민에 「계시다」는 어색해요.","고민에 「계시다」는 어색해요.","밀접한 대상에는 「있으시다」예요."]}'::jsonb),
