('g5_2_kor_u6_review_c#7','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C40',1,'ox','auto','감상을 나눌 때 친구의 답이 내 생각과 달라도 끝까지 들어요.',ARRAY['K5-2-u6-X40']::text[],false,'{"seq":7,"concept":"K5-2-u6-C40","difficulty":1,"kind":"ox","stem":"감상을 나눌 때 친구의 답이 내 생각과 달라도 끝까지 들어요.","answer":"O","reason_options":[{"t":"친구의 답에서 내가 생각하지 못한 의미를 발견할 수 있기 때문에","correct":true},{"t":"내 답과 다르면 친구의 답이 틀린 것이기 때문에","mis":"K5-2-u6-X40"}],"mis":"K5-2-u6-X40","explanation":["끝까지 들어요.","새 의미를 발견해요.","존중하며 나눠요."]}'::jsonb),
('g5_2_kor_u6_review_c#8','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C18',1,'ox','auto','인상 깊은 장면을 말할 때에는 그 장면을 고른 까닭도 함께 말해요.',ARRAY['K5-2-u6-X18']::text[],false,'{"seq":8,"concept":"K5-2-u6-C18","difficulty":1,"kind":"ox","stem":"인상 깊은 장면을 말할 때에는 그 장면을 고른 까닭도 함께 말해요.","answer":"O","reason_options":[{"t":"까닭을 들어야 친구가 내 감상을 이해하고 서로 견주어 볼 수 있기 때문에","correct":true},{"t":"장면 이름만 말하면 감상이 다 전해지기 때문에","mis":"K5-2-u6-X18"}],"mis":"K5-2-u6-X18","explanation":["까닭과 함께예요.","근거를 들어요.","서로 견주어 봐요."]}'::jsonb),
('g5_2_kor_u6_review_c#9','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C15',2,'mc','auto','「골목 끝 수선집」에서 할아버지의 마음을 가장 잘 짐작하게 하는 행동은 어느 것인가요?',ARRAY['K5-2-u6-X15']::text[],false,'{"seq":9,"concept":"K5-2-u6-C15","difficulty":2,"kind":"mc","stem":"「골목 끝 수선집」에서 할아버지의 마음을 가장 잘 짐작하게 하는 행동은 어느 것인가요?","options":[{"t":"밑창에 작은 글씨로 「끝까지」라고 새겨 주었다","correct":true},{"t":"안경을 코끝에 걸쳤다","mis":"K5-2-u6-X15"},{"t":"운동화를 이리저리 돌려 보았다","mis":"K5-2-u6-X15"},{"t":"수선집 문을 열어 두었다","mis":"K5-2-u6-X15"}],"explanation":["마음이 잘 드러나지 않아요.","마음이 잘 드러나지 않아요.","말 대신 응원을 새겨 주었어요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb),
('g5_2_kor_u6_review_c#10','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C31',2,'mc','auto','사서 선생님 역할을 맡은 친구가 인물에게 던질 질문으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X31']::text[],false,'{"seq":10,"concept":"K5-2-u6-C31","difficulty":2,"kind":"mc","stem":"사서 선생님 역할을 맡은 친구가 인물에게 던질 질문으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「사서 선생님은 왜 문을 닫지 않고 함께 기다리기로 했을까?」","correct":true},{"t":"「사서 선생님의 열쇠는 몇 개일까?」","mis":"K5-2-u6-X31"},{"t":"「도서관 책은 모두 몇 권일까?」","mis":"K5-2-u6-X31"},{"t":"「내 대사는 몇 줄일까?」","mis":"K5-2-u6-X31"}],"explanation":["마음과 관계없어요.","마음과 관계없어요.","그렇게 한 까닭을 물어요."],"asset":{"type":"passage","lines":["때: 비 오는 토요일 저녁 · 곳: 동네 작은 도서관 · 나오는 인물: 지안, 사서 선생님","책장 사이로 불빛이 하나둘 꺼지고, 창문에 빗방울이 맺혀 있다.","사서 선생님: (열쇠 꾸러미를 흔들며) 지안아, 이제 문 닫을 시간이란다.","지안: (책을 품에 꼭 안으며) 딱 한 장만 더 읽으면 안 돼요? 주인공이 곧 집에 돌아가거든요.","사서 선생님: (잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.","지안: (눈을 동그랗게 뜨고) 정말요? (책장을 넘기며 작은 소리로 읽기 시작한다.)"],"title":"극본 「도서관의 마지막 손님」"}}'::jsonb),
('g5_2_kor_u6_review_c#11','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C43',2,'ox','auto','어른과 관련된 말이면 무엇이든 「계시다」를 쓰면 높임 표현이 돼요.',ARRAY['K5-2-u6-X43']::text[],false,'{"seq":11,"concept":"K5-2-u6-C43","difficulty":2,"kind":"ox","stem":"어른과 관련된 말이면 무엇이든 「계시다」를 쓰면 높임 표현이 돼요.","answer":"X","reason_options":[{"t":"「계시다」는 어른을 직접 높일 때 쓰고, 말씀·고민처럼 밀접한 대상을 높일 때에는 「있으시다」를 쓰기 때문에","correct":true},{"t":"「계시다」가 「있으시다」보다 언제나 더 높이는 말이기 때문에","mis":"K5-2-u6-X43"}],"mis":"K5-2-u6-X43","explanation":["쓰임이 달라요.","밀접한 대상은 「있으시다」예요.","주어를 살펴요."]}'::jsonb),
