('g5_2_kor_u6_review_d#9','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C11',2,'mc','auto','「골목 끝 수선집」에서 달리기 대회 바로 전날이라는 때는 이야기에서 어떤 구실을 하나요?',ARRAY['K5-2-u6-X11']::text[],false,'{"seq":9,"concept":"K5-2-u6-C11","difficulty":2,"kind":"mc","stem":"「골목 끝 수선집」에서 달리기 대회 바로 전날이라는 때는 이야기에서 어떤 구실을 하나요?","options":[{"t":"서준이가 급하게 운동화를 고쳐야 하는 사건을 만든다","correct":true},{"t":"아무 구실도 하지 않는 장식이다","mis":"K5-2-u6-X11"},{"t":"할아버지의 이름을 알려 준다","mis":"K5-2-u6-X11"},{"t":"수선집이 있는 곳을 알려 준다","mis":"K5-2-u6-X11"}],"explanation":["배경은 장식이 아니에요.","이름과 관계없어요.","때가 사건을 만들어요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb),
('g5_2_kor_u6_review_d#10','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C28',2,'mc','auto','「도서관의 마지막 손님」에서 두 인물의 관계가 어떻게 바뀌었는지 알맞게 말한 것은 어느 것인가요?',ARRAY['K5-2-u6-X28']::text[],false,'{"seq":10,"concept":"K5-2-u6-C28","difficulty":2,"kind":"mc","stem":"「도서관의 마지막 손님」에서 두 인물의 관계가 어떻게 바뀌었는지 알맞게 말한 것은 어느 것인가요?","options":[{"t":"문을 닫으려던 선생님이 지안이 곁에서 함께 이야기를 기다리는 사이가 되었다","correct":true},{"t":"처음부터 끝까지 서로 다투는 사이이다","mis":"K5-2-u6-X28"},{"t":"지안이가 선생님을 도서관에서 내보냈다","mis":"K5-2-u6-X28"},{"t":"두 사람은 서로 말을 나누지 않았다","mis":"K5-2-u6-X28"}],"explanation":["다투지 않았어요.","극본과 달라요.","관계가 가까워졌어요."],"asset":{"type":"passage","lines":["때: 비 오는 토요일 저녁 · 곳: 동네 작은 도서관 · 나오는 인물: 지안, 사서 선생님","책장 사이로 불빛이 하나둘 꺼지고, 창문에 빗방울이 맺혀 있다.","사서 선생님: (열쇠 꾸러미를 흔들며) 지안아, 이제 문 닫을 시간이란다.","지안: (책을 품에 꼭 안으며) 딱 한 장만 더 읽으면 안 돼요? 주인공이 곧 집에 돌아가거든요.","사서 선생님: (잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.","지안: (눈을 동그랗게 뜨고) 정말요? (책장을 넘기며 작은 소리로 읽기 시작한다.)"],"title":"극본 「도서관의 마지막 손님」"}}'::jsonb),
